INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.511Z-000000-a2e30200-1f80-4dcf-9b98-a371a5e4433e', 6, '2026-10-17T15:38:46Z', 'Don de classe Double coup : Remarque ; Don de classe Double coup : Remarque ; Don de classe Totémiste : Remarque ; Don de classe Économe : Remarque', NULL, 'page', '{"id":"capacites/marcass-totemiste"}', 'modifier', '{"corps_md":"Peut se créer un totem de sa magie innée qui donne un bonus de terrain pour lui et ses alliés.  \nDure 3 tours.\n\nNote de cellule : Terre : Réduit les dégâts encaissés de 4.\n\nFeu : Augmente les dégâts infligés de 4.\n\nNécromancie : Économise 1 chakra à chaque sort lancé.\n"}', '{"corps_md":"Peut se créer un totem de sa magie innée qui donne un bonus de terrain pour lui et ses alliés.  \nDure 3 tours.\n\nNote de cellule : Terre : Réduit les dégâts encaissés de 4.\n\nFeu : Augmente les dégâts infligés de 4.\n\nNécromancie : Économise 1 {{chakra|chakra}} à chaque sort lancé.\n"}');
