INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.653Z-000000-4adc2795-ec78-4f78-b47c-ef0bf2bea9d6', 10, '2026-10-17T15:38:46Z', 'Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE C', NULL, 'monstre_rubrique', '{"monstre_id":"monstres/criquet-thaumivore#carte:gros-criquet-thaumivore","rang":11}', 'modifier', '{"texte":"Il a bien mangé celui-là ! Avec ses 80 cm en moyenne et sa plus grosse réserve de chakra, ses amplifications sont plus fortes."}', '{"texte":"Il a bien mangé celui-là ! Avec ses 80 cm en moyenne et sa plus grosse réserve de {{chakra|chakra}}, ses amplifications sont plus fortes."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.653Z-000000-4adc2795-ec78-4f78-b47c-ef0bf2bea9d6', 11, '2026-10-17T15:38:46Z', 'Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE C', NULL, 'monstre_rubrique', '{"monstre_id":"monstres/elementaire-de-la-necromancie#carte:elementaire-de-la-necromancie","rang":10}', 'modifier', '{"texte":"C’est un véritable rouleau compresseur, il va invoquer à la chaîne des non-morts différents pour pouvoir combattre ceux qui le menacent. La stratégie repose sur tuer rapidement ses invocations pour l’épuiser et le tuer à la longue.\n\nN’essayez pas de l’atteindre directement, sa cage d’os est trop épaisse pour lui mettre le moindre coup.\n(Oui sa barrière ne sert à rien)"}', '{"texte":"C’est un véritable rouleau compresseur, il va invoquer à la chaîne des non-morts différents pour pouvoir combattre ceux qui le menacent. La stratégie repose sur tuer rapidement ses invocations pour l’épuiser et le tuer à la longue.\n\nN’essayez pas de l’atteindre directement, sa cage d’os est trop épaisse pour lui mettre le moindre coup.\n(Oui sa {{barriere|barrière}} ne sert à rien)"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.653Z-000000-4adc2795-ec78-4f78-b47c-ef0bf2bea9d6', 12, '2026-10-17T15:38:46Z', 'Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE C', NULL, 'monstre_rubrique', '{"monstre_id":"monstres/elementaire-de-larcane#carte:elementaire-de-larcane","rang":12}', 'modifier', '{"texte":"L’anti mage par excellence, cet élémentaire fait vibrer le chakra de ses ennemis et malheur à ceux qui l''utilisent mal. Il est capable de faire des ravages contre ceux qui stocke beaucoup de chakra en eux.\n\nEt même si vous pensez être à l’abri en vidant votre réserve de chakra, les plus forts sont capables de vous redonner du chakra."}', '{"texte":"L’anti mage par excellence, cet élémentaire fait vibrer le {{chakra|chakra}} de ses ennemis et malheur à ceux qui l''utilisent mal. Il est capable de faire des ravages contre ceux qui stocke beaucoup de {{chakra|chakra}} en eux.\n\nEt même si vous pensez être à l’abri en vidant votre réserve de {{chakra|chakra}}, les plus forts sont capables de vous redonner du {{chakra|chakra}}."}');
