INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.653Z-000000-4adc2795-ec78-4f78-b47c-ef0bf2bea9d6', 18, '2026-10-17T15:38:46Z', 'Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte Dégâts : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE COMBAT : Texte de la rubrique ; Rubrique de la carte TACTIQUE C', NULL, 'monstre_rubrique', '{"monstre_id":"monstres/golem-de-corail#carte:golem-de-corail-i","rang":11}', 'modifier', '{"texte":"Ce golem très particulier possède la capacité de faire un souffle hydraulique sur ses ennemis mais c’est sa barrière qui semble en permanence se recharger.\nIl dispose de beaucoup de résistance élémentaire et il n’est pas inquiété par les dégâts d’estoc vu qu’il est immunité à ces derniers, il ne dispose pas de faiblesse aux dégâts de frappe comme les squelettes car sa composition lui permet de ne pas l’être."}', '{"texte":"Ce golem très particulier possède la capacité de faire un souffle hydraulique sur ses ennemis mais c’est sa {{barriere|barrière}} qui semble en permanence se recharger.\nIl dispose de beaucoup de résistance élémentaire et il n’est pas inquiété par les dégâts d’estoc vu qu’il est immunité à ces derniers, il ne dispose pas de faiblesse aux dégâts de frappe comme les squelettes car sa composition lui permet de ne pas l’être."}');
