INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 1, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"adaptation-elementaire"}', 'modifier', '{"description":"Cette créature ne possède pas la même forme selon l’environnement où on la rencontre, chaque environnement peut être associé à une magie, et lui donne différents bonus :\nSang = Élément sang, +7 dégâts avec les armes, 7AP/3AM\nArcane = Élément arcane, +7 dégâts avec le souffle, 2AP/8AM\nCorruption = Élément corruption, les attaques infligent 4 corruption, 2AP/8AM\nEspace/Temps = Élément espace/temps, les diagonales compte pour 1 case de déplacement, 4AP/6AM\nNécromancie = Élément sang, résistance aux dégâts d’estoc, 7AP/3AM\nFeu = Élément feu, infligent brûlure 2 avec le souffle, 5AP/5AM\nEau = Élément eau, régénère 5 barrière au début de chaque tour, 4AP/6AM\nGlace = Élément glace, malus de 3 à l’initiative aux ennemis à 2 cases, 0AP/10AM\nTerre = Élément terre, si santé en dessous de 25% = peut projeter des éclat de pierre sur un rayon de 4 cases qui infligent 4d10 dégâts, 10AP/0AM\nVent = Élément vent, inflige des dégâts sonore avec le souffle, 4AP/6AM\nFoudre = Élément foudre, possède une plaque miroir qui peut absorber un sort niveau 3, cette plaque réapparaît tous les 3 tours, 6AP/4AM\nLumière = Élément lumière, régénère 5 santé au début de chaque tour, 5AP/5AM\nOmbre = Élément ombre, chaque attaques infligent un malus de 10% au prochain jet de la victime, 5AP/5AM"}', '{"description":"Cette créature ne possède pas la même forme selon l’environnement où on la rencontre, chaque environnement peut être associé à une magie, et lui donne différents bonus :\nSang = Élément sang, +7 dégâts avec les armes, 7AP/3AM\nArcane = Élément arcane, +7 dégâts avec le souffle, 2AP/8AM\nCorruption = Élément corruption, les attaques infligent 4 corruption, 2AP/8AM\nEspace/Temps = Élément espace/temps, les diagonales compte pour 1 case de déplacement, 4AP/6AM\nNécromancie = Élément sang, résistance aux dégâts d’estoc, 7AP/3AM\nFeu = Élément feu, infligent brûlure 2 avec le souffle, 5AP/5AM\nEau = Élément eau, régénère 5 {{barriere|barrière}} au début de chaque tour, 4AP/6AM\nGlace = Élément glace, malus de 3 à l’initiative aux ennemis à 2 cases, 0AP/10AM\nTerre = Élément terre, si santé en dessous de 25% = peut projeter des éclat de pierre sur un rayon de 4 cases qui infligent 4d10 dégâts, 10AP/0AM\nVent = Élément vent, inflige des dégâts sonore avec le souffle, 4AP/6AM\nFoudre = Élément foudre, possède une plaque miroir qui peut absorber un sort niveau 3, cette plaque réapparaît tous les 3 tours, 6AP/4AM\nLumière = Élément lumière, régénère 5 santé au début de chaque tour, 5AP/5AM\nOmbre = Élément ombre, chaque attaques infligent un malus de 10% au prochain jet de la victime, 5AP/5AM"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 2, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"anti-barriere"}', 'modifier', '{"description":"L’arme de cette créature possède la même propriété que le maverium, il casse la barrière au moindre dégâts infligés."}', '{"description":"L’arme de cette créature possède la même propriété que le maverium, il casse la {{barriere|barrière}} au moindre dégâts infligés."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 3, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"blessure-chakratique"}', 'modifier', '{"description":"Cette créature exploite le chakra de ses adversaire à son avantage, elle obtient un bonus de 1 dégât à ses attaques par 5 chakra courant dans la réserve de sa cible. Quand ses ennemis utilisent du chakra, si leur score de réussite est au dessus de 75, ils perdent le quart du coût en chakra du sort en santé (minimum 1 santé)."}', '{"description":"Cette créature exploite le {{chakra|chakra}} de ses adversaire à son avantage, elle obtient un bonus de 1 dégât à ses attaques par 5 {{chakra|chakra}} courant dans la réserve de sa cible. Quand ses ennemis utilisent du {{chakra|chakra}}, si leur score de réussite est au dessus de 75, ils perdent le quart du coût en {{chakra|chakra}} du sort en santé (minimum 1 santé)."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 4, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"brulure-chakratique"}', 'modifier', '{"description":"Tant qu’elle est sur le terrain, cette créature augmente les coûts en chakra de 50% pour ses ennemis."}', '{"description":"Tant qu’elle est sur le terrain, cette créature augmente les coûts en {{chakra|chakra}} de 50% pour ses ennemis."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 5, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"cadeau-chakratique"}', 'modifier', '{"description":"Cette créature peut donner une partie de son chakra à une cible. (3 fois/combat)"}', '{"description":"Cette créature peut donner une partie de son {{chakra|chakra}} à une cible. (3 fois/combat)"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 6, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"charge-chakratique"}', 'modifier', '{"description":"Quand la réserve de chakra atteint 100%, peut faire une charge sur une cible dont la portée correspond au sprint de la créature. Une fois cette attaque faite, la réserve de chakra retombe à 0."}', '{"description":"Quand la réserve de {{chakra|chakra}} atteint 100%, peut faire une charge sur une cible dont la portée correspond au sprint de la créature. Une fois cette attaque faite, la réserve de {{chakra|chakra}} retombe à 0."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 7, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"chargement-bleu"}', 'modifier', '{"description":"Cette créature possède une réserve de chakra vide qui peut se remplir par un moyen x. Quand elle atteint certains seuil de réserve, elle débloque des passif qui se cumule entre eux :\n20% de chakra = +{3} Initiative\n40% de chakra = +{5} aux dégâts\n60% de chakra = +{1} vitesse\n80% de chakra = +{6} AM\n100% de chakra = Débloque le don “” et DOIT le faire dès que possible."}', '{"description":"Cette créature possède une réserve de {{chakra|chakra}} vide qui peut se remplir par un moyen x. Quand elle atteint certains seuil de réserve, elle débloque des passif qui se cumule entre eux :\n20% de {{chakra|chakra}} = +{3} Initiative\n40% de {{chakra|chakra}} = +{5} aux dégâts\n60% de {{chakra|chakra}} = +{1} vitesse\n80% de {{chakra|chakra}} = +{6} AM\n100% de {{chakra|chakra}} = Débloque le don “” et DOIT le faire dès que possible."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 8, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"chargement-bleu-2"}', 'modifier', '{"description":"Cette créature possède une réserve de chakra vide qui peut se remplir par un moyen x. Quand elle atteint certains seuil de réserve, elle débloque des passif qui se cumule entre eux :\n20% de chakra = +2 Initiative\n40% de chakra = +3 aux dégâts\n60% de chakra = +10% Esquive\n80% de chakra = +4 AM\n100% de chakra = Débloque le don “” et DOIT le faire dès que possible."}', '{"description":"Cette créature possède une réserve de {{chakra|chakra}} vide qui peut se remplir par un moyen x. Quand elle atteint certains seuil de réserve, elle débloque des passif qui se cumule entre eux :\n20% de {{chakra|chakra}} = +2 Initiative\n40% de {{chakra|chakra}} = +3 aux dégâts\n60% de {{chakra|chakra}} = +10% Esquive\n80% de {{chakra|chakra}} = +4 AM\n100% de {{chakra|chakra}} = Débloque le don “” et DOIT le faire dès que possible."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 9, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"crache-feu"}', 'modifier', '{"description":"Contre 3IC, cette créature peut cracher une gerbe de flamme qui va à 3 PO en ligne droite et touché toutes les créatures dans la zone, inflige 3d6 dégâts. Coûte 5 chakra."}', '{"description":"Contre 3IC, cette créature peut cracher une gerbe de flamme qui va à 3 PO en ligne droite et touché toutes les créatures dans la zone, inflige 3d6 dégâts. Coûte 5 {{chakra|chakra}}."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 10, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"cuisson-absolue"}', 'modifier', '{"description":"La peau de cette créature réagit aux éléments qu’on lui inflige, changeant sa peau et lui donne des propriétés. Cet état dure 3 tours tant qu’un autre élément n’est pas utilisé pour le remplacer, au bout de 3 tours, il redevient neutre. Utiliser un élément contraire à celui actif enclenche une “contre-cuisson”, l’effet de contre cuisson peut être esquiver ou parer s’il inflige des dégâts (sauf contre indication).\nVoir le tableau plus bas.\n\nÉlément\nEffets/Description\nRésistance Vulnérabilité\nSang\nMiche sacrificielle\nÉlément Sang\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nFolle de guerre\n\n+12 dégâts mais perd 5% de sa santé max à chaque coup réussi ou raté.\n\nSi touché par faiblesse :\nUn nuage mauvais est invoqué, pendant 1 tour, les soins prodigués sont divisés par 2.\nRésistance : Sang\n\nVulnérabilité : Nécromancie\nArcane\nPain blanc\nÉlément Arcane\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nRenvoi à hauteur de 25% des effets du sort de l’adversaire (l’agresseur peut se défendre contre cette contre attaque si c’est possible)\n\n+2 AM\n\nSi touché par faiblesse :\nUne explosion se produit, force les ennemis un jet de fermeté, si ils ratent : Perd 3d10 chakra.\nRésistance : Arcane\n\nVulnérabilité : Corruption\nCorruption\nPain noir\nÉlément Corruption\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nPossède une aura négative de 2 cases de rayon, les ennemis à l’intérieur ont un malus de 5% à tout leur jets.\n\n+2 AP\n\nSi touché par faiblesse :\nUne explosion noire se produit, inflige autant de corruption que le dernier sort subi à coûté en chakra.\nRésistance : Corruption\n\nVulnérabilité : Arcane\nEspace/Temps\nCuisson instable\nÉlément Espace/Temps\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1.\n\nPossède une esquive/parade supplémentaire peu importe la posture\n\n+2 INI\n\nSi touché par faiblesse :\nUne implosion se produit, annule toutes amplifications positives et négatives sur tout le monde.\nRésistance : Espace/Temps\n\nVulnérabilité :\nVide\nVide\nCuisson creuse\nÉlément Vide\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nDégâts divisé par 2\n\nSes armes ignorent les défenses ennemies.\n\nSi touché par faiblesse :\nSes deux initiatives seront en premier et dernier quoi qu’il arrive pour le prochain tour.\nRésistance : Vide\n\nVulnérabilité : Espace/Temps\nNécromancie\nMiche moisie\nÉlément Nécromancie\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\n+5 AP\n\nDraine la santé de ses ennemis à hauteur de 10% des dégâts infligés.\n\n-6 dégâts\n\nSi touché par faiblesse :\nUne onde choc retentit sur le terrain et inflige 10 dégâts de sang perce AM et force un jet de vigueur à ceux qui sont touchés, s''ils ratent : Malus de 20% au prochain test pour éviter une altération d’état.\nRésistance : Nécromancie\n\nVulnérabilité : Sang\nFeu\nCaramélisation\nÉlément Feu\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\n+3 dégâts\n\n+2 AP\n\nSi touché par faiblesse :\n(Défense impossible) Invoque un nuage sur le terrain pendant 1 tour, inflige 10 dégâts de glace perce AM aux ennemis et impose un malus de 10% pour toucher une cible.\nRésistance : Feu\n\nVulnérabilité : Glace\nEau\nCroûte imbibé\nÉlément Eau\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nLa régénération lui donne 15 santé au lieu de 10.\n\n+5 AM\n\n-3 Initiative\n\nSi touché par faiblesse :\nProvoque un violent arc électrique autour de lui, inflige 20 dégâts de foudre dans un rayon de 6 cases autour et force un jet de vigueur, si c’est raté : Bloque le sprint pour le prochain tour.\nRésistance : Eau\n\nVulnérabilité : Foudre\nGlace\nCongélation\nÉlément Glace\n\n40% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\n+10 AM\n\n-1 vitesse\n\nSi touché par faiblesse :\n(Défense impossible)\nProduit une poussée autour du golem qui inflige 10 dégâts de feu perce AM et repousse de 4 cases les cibles à 1-2 cases de lui.\nRésistance : Glace\n\nVulnérabilité : Feu\nTerre\nLevain rustique\nÉlément Terre\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\n+5 dégâts\n\n+10 AP\n\n-1 Vitesse\n\nSi touché par faiblesse :\nExplosion de fragments de croûte de pain, inflige 20 dégâts de taille/vent à tous les ennemis dans un rayon de 6 cases.\nRésistance : Terre\n\nVulnérabilité : Vent\nVent\nLevain actif\nÉlément Vent\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\n+1 Vitesse\n\nSi touché par faiblesse :\nProvoque une onde de choc, inflige 10 dégâts de terre perce AM et force un jet de stabilité/réflexe pour ne pas tomber au sol.\nRésistance : Vent\n\nVulnérabilité : Terre\nFoudre\nCroûte électrique\nÉlément Foudre\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\n+3 dégâts\n\n+10 Initiative\n\nSi touché par faiblesse :\n\nRésistance : Foudre\n\nVulnérabilité : Eau\nLumière\nDorure sacré\nÉlément Lumière\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nAnnule 5 dégâts d’une attaque encaissée, cette réduction se recharge après chaque attaque et elle n’est pas affectée par les attaques qui ignorent les défenses.\n\nSi touché par faiblesse :\nToute la lumière se libère d’un coup, forçant un jet de vigueur aux ennemis qui le voit, ceux qui rate encaissent aveuglement 2 pendant 2 tours.\nRésistance : Lumière\n\nVulnérabilité : Ombre\nOmbre\nDorure maudite\nÉlément Ombre\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nL’attaque de cette créature possède l’effet du sort “Malédiction” de la magie de l’ombre et l’impose pour 1 tour à la victime.\n\nSi touché par faiblesse :\nL’ombre de la créature se manifeste le temps d’une attaque et va frapper l’ennemi le plus proche avec les mêmes dégâts que le golem.\nRésistance : Ombre\n\nVulnérabilité : Lumière\nNeutre\n(c’est de le cas où il n’a pas subi de dégâts magique encore)\n\nAucune propriété\nRésistant à tous les dégâts physiques"}', '{"description":"La peau de cette créature réagit aux éléments qu’on lui inflige, changeant sa peau et lui donne des propriétés. Cet état dure 3 tours tant qu’un autre élément n’est pas utilisé pour le remplacer, au bout de 3 tours, il redevient neutre. Utiliser un élément contraire à celui actif enclenche une “contre-cuisson”, l’effet de contre cuisson peut être esquiver ou parer s’il inflige des dégâts (sauf contre indication).\nVoir le tableau plus bas.\n\nÉlément\nEffets/Description\nRésistance Vulnérabilité\nSang\nMiche sacrificielle\nÉlément Sang\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nFolle de guerre\n\n+12 dégâts mais perd 5% de sa santé max à chaque coup réussi ou raté.\n\nSi touché par faiblesse :\nUn nuage mauvais est invoqué, pendant 1 tour, les soins prodigués sont divisés par 2.\nRésistance : Sang\n\nVulnérabilité : Nécromancie\nArcane\nPain blanc\nÉlément Arcane\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nRenvoi à hauteur de 25% des effets du sort de l’adversaire (l’agresseur peut se défendre contre cette contre attaque si c’est possible)\n\n+2 AM\n\nSi touché par faiblesse :\nUne explosion se produit, force les ennemis un jet de fermeté, si ils ratent : Perd 3d10 {{chakra|chakra}}.\nRésistance : Arcane\n\nVulnérabilité : Corruption\nCorruption\nPain noir\nÉlément Corruption\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1\n\nPossède une aura négative de 2 cases de rayon, les ennemis à l’intérieur ont un malus de 5% à tout leur jets.\n\n+2 AP\n\nSi touché par faiblesse :\nUne explosion noire se produit, inflige autant de corruption que le dernier sort subi à coûté en {{chakra|chakra}}.\nRésistance : Corruption\n\nVulnérabilité : Arcane\nEspace/Temps\nCuisson instable\nÉlément Espace/Temps\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre l’altération d’état de la magie stade 1.\n\nPossède une esquive/parade supplémentaire peu importe la posture\n\n+2 INI\n\nSi touché par faiblesse :\nUne implosion se produit, annule toutes amplifications positives et négatives sur tout le monde.\nRésistance : Espace/Temps\n\nVulnérabilité :\nVide\nVide\nCuisson creuse\nÉlément Vide\n\n20% de chance de forcer un jet de vigueur aux ennemis pour ne pas prendre 