INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 11, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"effondrement-chakratique"}', 'modifier', '{"description":"Son chakra s’effondre et sa magie est hors de contrôle, cette créature obtient quatres dons selon si elle est mono magie ou bi-magie. Voir tableau plus bas."}', '{"description":"Son {{chakra|chakra}} s’effondre et sa magie est hors de contrôle, cette créature obtient quatres dons selon si elle est mono magie ou bi-magie. Voir tableau plus bas."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 12, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"element-aleatoire"}', 'modifier', '{"description":"Cette créature peut être de différentes formes et possède un bonus différent selon la magie auquel il est relié. Et avec tout ça, une de ses armes* naturelles est capable d''infliger l’élément relié.\nSang = Force le jet de vigueur/fermeté à chaque attaque réussi pour empêcher le marquage\nArcane = Retire 1d6 chakra à la cible\nCorruption = Inflige 4 corruption a chaque attaque réussi\nEspace/Temps = Retire 1 vitesse à la cible pour son prochain tour à chaque attaque réussi\nVide = Force le jet de vigueur/fermeté à chaque attaque réussi pour empêcher le silence\nNécromancie = Pose une charge de nécrose, au bout de 5 charges, la cible tombe dans le coma\nFeu = Bonus de +3 aux dégâts\nEau = Soigne une altération d’état à chaque début de tour\nGlace = Double l’AM\nTerre = Double l’AP\nVent = +1 Vitesse\nFoudre = +5 INI\nLumière = Régénère 5 santé au début de chaque tour\nOmbre = Attaque sournoise"}', '{"description":"Cette créature peut être de différentes formes et possède un bonus différent selon la magie auquel il est relié. Et avec tout ça, une de ses armes* naturelles est capable d''infliger l’élément relié.\nSang = Force le jet de vigueur/fermeté à chaque attaque réussi pour empêcher le marquage\nArcane = Retire 1d6 {{chakra|chakra}} à la cible\nCorruption = Inflige 4 corruption a chaque attaque réussi\nEspace/Temps = Retire 1 vitesse à la cible pour son prochain tour à chaque attaque réussi\nVide = Force le jet de vigueur/fermeté à chaque attaque réussi pour empêcher le silence\nNécromancie = Pose une charge de nécrose, au bout de 5 charges, la cible tombe dans le coma\nFeu = Bonus de +3 aux dégâts\nEau = Soigne une altération d’état à chaque début de tour\nGlace = Double l’AM\nTerre = Double l’AP\nVent = +1 Vitesse\nFoudre = +5 INI\nLumière = Régénère 5 santé au début de chaque tour\nOmbre = Attaque sournoise"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 13, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"forme-meteo-plus"}', 'modifier', '{"description":"Cette créature possède une structure particulière qui fait qu’elle se modifier selon la météo, elle possède également 10% de chance de forcer un jet de vigueur/fermeté à son adversaire pour ne pas qu’il encaisse l’altération d’état lié à son/ses élément(s) :\nNeutre : +10 dégâts avec les armes\nGrand soleil : Élément Lumière, les soins ennemis sont réduits au lieu d’être amplifiés.\nCanicule : Élément Feu, malus de 20% pour esquiver les brûlures.\nPluie : Élément Eau, +20% de chance en plus d’infliger “confusion 1”.\nPluie diluvienne : Élément Eau, la météo inflige 2d6 dégâts non élémentaire au début de chaque tour.\nNeige : Élément Glace, double l’AM.\nTempête de neige : Élément Glace, triple l’AM.\nVent violent : Élément Vent, +2 vitesse et INI.\nBrouillard : Élément Nécromancie, malus de 10% aux ennemis pour toucher la créature.\nPurée de pois : Élément Nécromancie, malus de 20% aux ennemis pour toucher la créature.\nBrouillard obscur : Élément Ombre, pose l’effet du sort “malédiction” pendant un tour sur la cible après une attaque réussi.\nOrage : Élément Foudre et Espace/Temps, +20% de chance en plus d’infliger “paralysie 1”.\nChamp magnétique : Élément Foudre et Terre, double l’AP.\nTempête de sable : Élément Vent et Terre, double l’AP.\nLune de sang : Élément Sang, la créature peut faire les sorts “Sang” en IC sans jet et sans coût (sauf le Sang perfection)\nÉclipse : Élément Lumière et Ombre, les magies désavantagées sont tout simplement désactivées.\nCrachin blanc : Élément Arcane, chaque attaque brûlera 2d6 chakra à la cible.\nPluie pétrole : Élément Corruption, chaque attaque inflige 2d4 corruption.\nSaccage temporel : Élément Vide, au début de chaque tour - un ennemi aléatoire va voir sa magie désactivée."}', '{"description":"Cette créature possède une structure particulière qui fait qu’elle se modifier selon la météo, elle possède également 10% de chance de forcer un jet de vigueur/fermeté à son adversaire pour ne pas qu’il encaisse l’altération d’état lié à son/ses élément(s) :\nNeutre : +10 dégâts avec les armes\nGrand soleil : Élément Lumière, les soins ennemis sont réduits au lieu d’être amplifiés.\nCanicule : Élément Feu, malus de 20% pour esquiver les brûlures.\nPluie : Élément Eau, +20% de chance en plus d’infliger “confusion 1”.\nPluie diluvienne : Élément Eau, la météo inflige 2d6 dégâts non élémentaire au début de chaque tour.\nNeige : Élément Glace, double l’AM.\nTempête de neige : Élément Glace, triple l’AM.\nVent violent : Élément Vent, +2 vitesse et INI.\nBrouillard : Élément Nécromancie, malus de 10% aux ennemis pour toucher la créature.\nPurée de pois : Élément Nécromancie, malus de 20% aux ennemis pour toucher la créature.\nBrouillard obscur : Élément Ombre, pose l’effet du sort “malédiction” pendant un tour sur la cible après une attaque réussi.\nOrage : Élément Foudre et Espace/Temps, +20% de chance en plus d’infliger “paralysie 1”.\nChamp magnétique : Élément Foudre et Terre, double l’AP.\nTempête de sable : Élément Vent et Terre, double l’AP.\nLune de sang : Élément Sang, la créature peut faire les sorts “Sang” en IC sans jet et sans coût (sauf le Sang perfection)\nÉclipse : Élément Lumière et Ombre, les magies désavantagées sont tout simplement désactivées.\nCrachin blanc : Élément Arcane, chaque attaque brûlera 2d6 {{chakra|chakra}} à la cible.\nPluie pétrole : Élément Corruption, chaque attaque inflige 2d4 corruption.\nSaccage temporel : Élément Vide, au début de chaque tour - un ennemi aléatoire va voir sa magie désactivée."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 14, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"lame-foudroyante"}', 'modifier', '{"description":"(IC) En échange de 5 chakra, la prochaine attaque physique au contact libère une foudre qui inflige 1d8 dégâts qui va ignorer l’AM et l’AP de la cible."}', '{"description":"(IC) En échange de 5 {{chakra|chakra}}, la prochaine attaque physique au contact libère une foudre qui inflige 1d8 dégâts qui va ignorer l’AM et l’AP de la cible."}');
