INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 25, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"serviteur-toxique"}', 'modifier', '{"description":"Cette créature n’attaque pas directement, elle se cache derrière une cage d’os indestructible et lance ses invocations contre ses ennemis, elle peut en invoquer 4 à la fois, sans jet, a accès à toutes les invocations de la nécromancie et les remplace le tour après leur mort. Une fois qu’une invocation est tuée, la santé qu’elle possédait sera infligée contre la santé du boss (pas sa barrière). Il peut lancer les invocations selon son niveau de puissance magique."}', '{"description":"Cette créature n’attaque pas directement, elle se cache derrière une cage d’os indestructible et lance ses invocations contre ses ennemis, elle peut en invoquer 4 à la fois, sans jet, a accès à toutes les invocations de la nécromancie et les remplace le tour après leur mort. Une fois qu’une invocation est tuée, la santé qu’elle possédait sera infligée contre la santé du boss (pas sa {{barriere|barrière}}). Il peut lancer les invocations selon son niveau de puissance magique."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 26, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"sucon"}', 'modifier', '{"description":"Chaque attaque redonne de la santé ou de la barrière (selon ce qui est touché) à hauteur de 50% des dégâts infligés."}', '{"description":"Chaque attaque redonne de la santé ou de la {{barriere|barrière}} (selon ce qui est touché) à hauteur de 50% des dégâts infligés."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.705Z-000000-013156dd-f16f-41de-a2b2-a3f29013fde5', 27, '2026-10-17T15:38:46Z', 'Capacité de monstre Adaptation élémentaire : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Anti-barrière : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Blessure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur que chaque carte peut changer) ; Capacité de monstre Brûlure chakratique : Description (sur toutes ses cartes ; « {10} » : une valeur', NULL, 'monstre_capacite_commune', '{"id":"super-barriere"}', 'modifier', '{"description":"Cette créature possède une barrière qui correspond à son chakra."}', '{"description":"Cette créature possède une {{barriere|barrière}} qui correspond à son {{chakra|chakra}}."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 1, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":1}', 'modifier', '{"texte":"DESCRIPTION\nUn énorme tatouage sur le dos et le torse apparaît, le symbole de l’absolu complètement déformé. Les tatouages orange brillent d’une couleur dérangeante.\nCompétence\n+7% à toutes les compétences\nDon\nCarapace déformée. N’est plus vulnérable aux dégâts physiques.\n\nGrimoire déformé. A accès aux sorts de son niveau mais ne peut pas les utiliser deux fois de suite dans le même tour.\n\nRituel souillé. Capable d’utiliser les sorts sang, nécromancie et corruption sans la 4ème barre mais augmente de 50% le coût chakra.\n\nSemi-complet. Peut utiliser les sorts de lvl4 de puissance (si il a le niveau)"}', '{"texte":"DESCRIPTION\nUn énorme tatouage sur le dos et le torse apparaît, le symbole de l’absolu complètement déformé. Les tatouages orange brillent d’une couleur dérangeante.\nCompétence\n+7% à toutes les compétences\nDon\nCarapace déformée. N’est plus vulnérable aux dégâts physiques.\n\nGrimoire déformé. A accès aux sorts de son niveau mais ne peut pas les utiliser deux fois de suite dans le même tour.\n\nRituel souillé. Capable d’utiliser les sorts sang, nécromancie et corruption sans la 4ème barre mais augmente de 50% le coût {{chakra|chakra}}.\n\nSemi-complet. Peut utiliser les sorts de lvl4 de puissance (si il a le niveau)"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 2, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":3}', 'modifier', '{"texte":"DESCRIPTION\nLes marques de chakra vont briller d''une lumière particulièrement désagréable et libérer du chakra quasiment liquide. Sa peau devient parfaitement argenté.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence d’intelligence\n+7% compétence d’intelligence\nDon\nDon mono-magie\nAccalmie. Force la météo Neutre\n\nPuissance. +2/EP dégâts avec les sorts.\n\nMiroir partiel. Renvoi à hauteur de 25% des effets du sort de l’adversaire (l’agresseur peut se défendre contre cette contre attaque si c’est possible)\n\nRune immédiate. Cette créature obtient une résistance à l''élément du dernier sort subit et cela plusieurs fois dans un tour. (Une seule résistance à la fois)"}', '{"texte":"DESCRIPTION\nLes marques de {{chakra|chakra}} vont briller d''une lumière particulièrement désagréable et libérer du {{chakra|chakra}} quasiment liquide. Sa peau devient parfaitement argenté.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence d’intelligence\n+7% compétence d’intelligence\nDon\nDon mono-magie\nAccalmie. Force la météo Neutre\n\nPuissance. +2/EP dégâts avec les sorts.\n\nMiroir partiel. Renvoi à hauteur de 25% des effets du sort de l’adversaire (l’agresseur peut se défendre contre cette contre attaque si c’est possible)\n\nRune immédiate. Cette créature obtient une résistance à l''élément du dernier sort subit et cela plusieurs fois dans un tour. (Une seule résistance à la fois)"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 3, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":4}', 'modifier', '{"texte":"DESCRIPTION\nLes marques de corruption vont briller d''une lumière particulièrement désagréable et libérer de la corruption quasiment liquide. Sa peau devient progressivement noire.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence d’intelligence\n+7% compétence d’intelligence\nDon\nDon mono-magie\nPollution. Chaque attaque qui touche oblige un jet de vigueur qui donne ces effets pendant 2 tours =\n- Si réussite : diminue aléatoirement une résistance.\n- Si échec : aggrave une vulnérabilité aléatoirement.\n(Dans le cas de l''arcane et corruption, ça ne fonctionne pas)\n\nCicatrices pétrolières. Chaque attaque réussit empêche la cible de récupérer de la barrière pendant 1 tour.\nPoison Noir. Les attaques de cette créature ajoutent 10% des dégâts infligés en corruption.\n\nContestation. Chaque malus qui lui est infligé deviendra un bonus."}', '{"texte":"DESCRIPTION\nLes marques de corruption vont briller d''une lumière particulièrement désagréable et libérer de la corruption quasiment liquide. Sa peau devient progressivement noire.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence d’intelligence\n+7% compétence d’intelligence\nDon\nDon mono-magie\nPollution. Chaque attaque qui touche oblige un jet de vigueur qui donne ces effets pendant 2 tours =\n- Si réussite : diminue aléatoirement une résistance.\n- Si échec : aggrave une vulnérabilité aléatoirement.\n(Dans le cas de l''arcane et corruption, ça ne fonctionne pas)\n\nCicatrices pétrolières. Chaque attaque réussit empêche la cible de récupérer de la {{barriere|barrière}} pendant 1 tour.\nPoison Noir. Les attaques de cette créature ajoutent 10% des dégâts infligés en corruption.\n\nContestation. Chaque malus qui lui est infligé deviendra un bonus."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 4, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":5}', 'modifier', '{"texte":"DESCRIPTION\nLes bandages des mains et pieds se développent et sont présents sur tout le corps.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence d’intelligence\n+7% compétence d’intelligence\nDon\nDon mono-magie\nDiagonale incohérente. Les diagonales comptent pour 1 case de déplacement au lieu de 2.\n\nEn tête. L''une des initiatives de cette créature sera toujours au dessus de toutes les autres (Joueurs compris)\n\n25h. Cette créature est capable d''utiliser un sortilège du Temps et de l''Espace qui est capable de placement, ce sort n''infligera aucun dégâts ni aucun effet secondaire, juste elle fera son effet de déplacement. Cette action peut se faire avant ou après le tour réel de la créature. (Ne demande pas de chakra)\n\nRedémarrage. Permet de relancer un échec (hors échec critique) (réaction 1 fois/3 tours)"}', '{"texte":"DESCRIPTION\nLes bandages des mains et pieds se développent et sont présents sur tout le corps.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence d’intelligence\n+7% compétence d’intelligence\nDon\nDon mono-magie\nDiagonale incohérente. Les diagonales comptent pour 1 case de déplacement au lieu de 2.\n\nEn tête. L''une des initiatives de cette créature sera toujours au dessus de toutes les autres (Joueurs compris)\n\n25h. Cette créature est capable d''utiliser un sortilège du Temps et de l''Espace qui est capable de placement, ce sort n''infligera aucun dégâts ni aucun effet secondaire, juste elle fera son effet de déplacement. Cette action peut se faire avant ou après le tour réel de la créature. (Ne demande pas de {{chakra|chakra}})\n\nRedémarrage. Permet de relancer un échec (hors échec critique) (réaction 1 fois/3 tours)"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 5, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":6}', 'modifier', '{"texte":"DESCRIPTION\nSon torse entier est vide ainsi que ses yeux.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de volonté\n+7% compétence de volonté\nDon\nDon mono-magie\nCorps vide. Le torse de cette créature est totalement invulnérable aux dégâts.\n\nLévitation. N''est pas affecté par les effets qui impliquent le sol.\nAttaque vide. L''attaque de cette créature bloque l''utilisation de la magie de la victime pour 1 tour.\n\nMigraine chakratique. Les ennemis à 3 cases autour de la créature voient leur coût en chakra augmenter de 25% pour leur sort."}', '{"texte":"DESCRIPTION\nSon torse entier est vide ainsi que ses yeux.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de volonté\n+7% compétence de volonté\nDon\nDon mono-magie\nCorps vide. Le torse de cette créature est totalement invulnérable aux dégâts.\n\nLévitation. N''est pas affecté par les effets qui impliquent le sol.\nAttaque vide. L''attaque de cette créature bloque l''utilisation de la magie de la victime pour 1 tour.\n\nMigraine chakratique. Les ennemis à 3 cases autour de la créature voient leur coût en {{chakra|chakra}} augmenter de 25% pour leur sort."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 6, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":8}', 'modifier', '{"texte":"DESCRIPTION\nLa moitié du corps est complètement brûlé et crache des flammes très brûlantes en permanence.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de force\n+7% compétence de force\nDon\nDon mono-magie\nMoteur thermique. Cette créature absorbe les dégâts de l’élément feu, si une attaque de feu est tenté sur lui, ses dégâts augmente de 5 et sa vitesse de 1 pendant 2 tours.\n\nJet de Magma. Cette créature lance du magma et diminue de 2 la résistance au Feu de la cible.\nDéflagration. Sacrifie les AP ou AM pour les ajouter à ses dégâts pendant 2 tours.\n\nCrache feu. Contre 3IC, cette créature peut cracher une gerbe de flamme qui va à 3 PO en ligne droite et touché toutes les créatures dans la zone, inflige 3d6 dégâts. Coût 5 chakra."}', '{"texte":"DESCRIPTION\nLa moitié du corps est complètement brûlé et crache des flammes très brûlantes en permanence.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de force\n+7% compétence de force\nDon\nDon mono-magie\nMoteur thermique. Cette créature absorbe les dégâts de l’élément feu, si une attaque de feu est tenté sur lui, ses dégâts augmente de 5 et sa vitesse de 1 pendant 2 tours.\n\nJet de Magma. Cette créature lance du magma et diminue de 2 la résistance au Feu de la cible.\nDéflagration. Sacrifie les AP ou AM pour les ajouter à ses dégâts pendant 2 tours.\n\nCrache feu. Contre 3IC, cette créature peut cracher une gerbe de flamme qui va à 3 PO en ligne droite et touché toutes les créatures dans la zone, inflige 3d6 dégâts. Coût 5 {{chakra|chakra}}."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 7, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":14}', 'modifier', '{"texte":"DESCRIPTION\nLe corps brille d''une lumière tamisée et négative, les yeux sont parfaitement beige. Les ailes de chakra sont de couleur beige cassé.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de perception\n+7% compétence de perception\nDon\nDon mono-magie\nPour moi. Si un adversaire est soigné à 2 cases de lui, le soin lui est transféré.\n\nForce Solaire. Perd 5% de sa santé à la fin de chacun de ses tours mais a un bonus de 10 à toutes ses attaques (15 si il y a la météo \"grand soleil\").\nRefus beige. Cette créature tout les tours va désigner un adversaire au hasard, ce dernier ne pourra ni lancer de sort de soin, ni être soigné.\n\nDeux fois plus. Peut lancer deux sorts d’amplification, soin ou protection en 1 tour. Demande un jet de concentration entre les deux sorts."}', '{"texte":"DESCRIPTION\nLe corps brille d''une lumière tamisée et négative, les yeux sont parfaitement beige. Les ailes de {{chakra|chakra}} sont de couleur beige cassé.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de perception\n+7% compétence de perception\nDon\nDon mono-magie\nPour moi. Si un adversaire est soigné à 2 cases de lui, le soin lui est transféré.\n\nForce Solaire. Perd 5% de sa santé à la fin de chacun de ses tours mais a un bonus de 10 à toutes ses attaques (15 si il y a la météo \"grand soleil\").\nRefus beige. Cette créature tout les tours va désigner un adversaire au hasard, ce dernier ne pourra ni lancer de sort de soin, ni être soigné.\n\nDeux fois plus. Peut lancer deux sorts d’amplification, soin ou protection en 1 tour. Demande un jet de concentration entre les deux sorts."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.735Z-000000-53813f3d-e233-40f2-9dd4-ccdec7c7caff', 8, '2026-10-17T15:38:46Z', 'Bloc de l’espèce POTENTIEL ILLIMITÉ : Texte du bloc ; Bloc de l’espèce ARCANE : Texte du bloc ; Bloc de l’espèce CORRUPTION : Texte du bloc ; Bloc de l’espèce ESPACE/TEMPS : Texte du bloc ; Bloc de l’espèce VIDE : Texte du bloc ; Bloc de l’espèce FEU : Texte du bloc ; Bloc de l’espèce LUMIÈRE : Texte du bloc ; Bloc de l’espèce OMBRE : Texte du bloc', NULL, 'monstre_espece_bloc', '{"espece_id":"monstres/presque-ottar","rang":15}', 'modifier', '{"texte":"DESCRIPTION\nL''aura d''ombre est surdéveloppé et les attributs de l’ombre sont totalement exagérés.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de perception\n+7% compétence de perception\nDon\nDon mono-magie\nDestructeur. 25% des dégâts des attaques sont infligés également au Chakra.\n\nDégénérer des ténèbres. Impose un malus de 10% aux jets de parade/esquive/fermeté/vigueur aux ennemis à 2 cases.\n\nChat noir. Les malus dure deux fois plus longtemps.\n\nAttaque maudite. La prochaine attaque réussi appliquera l''effet \"malédiction\" sur l''ennemi pendant 1 tour."}', '{"texte":"DESCRIPTION\nL''aura d''ombre est surdéveloppé et les attributs de l’ombre sont totalement exagérés.\nCompétence mono magie\nCompétence bi-magie\n+15% compétence de perception\n+7% compétence de perception\nDon\nDon mono-magie\nDestructeur. 25% des dégâts des attaques sont infligés également au {{chakra|Chakra}}.\n\nDégénérer des ténèbres. Impose un malus de 10% aux jets de parade/esquive/fermeté/vigueur aux ennemis à 2 cases.\n\nChat noir. Les malus dure deux fois plus longtemps.\n\nAttaque maudite. La prochaine attaque réussi appliquera l''effet \"malédiction\" sur l''ennemi pendant 1 tour."}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.744Z-000000-107e96fe-fdf5-490b-9828-134b98bab58d', 1, '2026-10-17T15:38:46Z', 'Butin {"espece_id":"monstres/blob-blanc","rang":8,"categorie":"boss"} : Butin possible ; Butin {"espece_id":"monstres/blob-blanc","rang":8,"categorie":"ennemi_simple"} : Butin possible ; Butin {"espece_id":"monstres/blob-blanc","rang":8,"categorie":"mini_boss"} : Butin possible ; Butin {"espece_id":"monstres/blob-bleu","rang":8,"categorie":"boss"} : Butin possible ; Butin {"espece_id":"monstres/blob-bleu","rang":8,"categorie":"ennemi_simple"} : Butin possible ; Butin {"espece_id":"monstres/blob-', NULL, 'monstre_butin', '{"espece_id":"monstres/blob-blanc","rang":8,"categorie":"boss"}', 'modifier', '{"texte":"Bloque la régénération de chakra pour 24h"}', '{"texte":"Bloque la régénération de {{chakra|chakra}} pour 24h"}');
