INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.797Z-000000-82c236a8-4538-4ef6-95e9-7722d68452d5', 10, '2026-10-17T15:38:46Z', 'Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-degoutant"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-etrange"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-amer"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-immonde"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:fiole-blanche-moyenne"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:meg', NULL, 'page', '{"id":"ressources/fiole-blanche"}', 'modifier', '{"corps_md":"*Les Fioles Blanches sont des potions conçues pour restaurer le chakra de manière progressive sur une longue durée. Contrairement aux fioles bleues qui permettent une récupération rapide, celles-ci diffusent leur effet lentement, alimentant le flux de chakra du corps au fil du temps. Elles sont souvent utilisées lors de périodes de repos, de méditation ou pendant des soins prolongés liés à l’épuisement du chakra.*\n\n*La Fiole Blanche se reconnaît à sa couleur blanche laiteuse et à son odeur douce rappelant la pêche mûre. Une fois consommée, elle procure une sensation de calme et de légèreté mentale, tandis que le chakra se régénère progressivement. La version la plus puissante de cette fiole possède toutefois un effet rare : elle peut augmenter de façon permanente la réserve maximale de chakra de celui qui la boit. Cet effet exceptionnel ne se manifeste qu’une seule fois par individu, pour une raison que les alchimistes ne parviennent toujours pas à expliquer.*\n\n| Recette |  |  |  |  |  |\n| :-: | :-: | :-: | :-: | :-: | :-: |\n| Solvant | Essence | Amplificateur | Catalyseur | Stabilisateur | Amplificateur majeur |\n| Fiole | Régénération chakra | Régénération chakra | Régénération chakra | Régénération chakra | Régénération chakra |\n\n| Petite fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 7 Ro | Novice | Régénère 5 chakra chaque tour. Dure 3 tours |\n\n| Fiole blanche moyenne |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 35 Ro | Apprenti | Régénère 10 chakra chaque tour. Dure 3 tours |\n\n| Super fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 75 Ro | Avancé | Régénère 20 chakra chaque tour. Dure 3 tours |\n\n| Méga fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 170 Ro | Expert | Régénère 40 chakra chaque tour. Dure 3 tours |\n\n| Ultime fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 300 Ro | Maître | Augmente la chakra maximum de 10 (une fois par personnage) |\n"}', '{"corps_md":"*Les Fioles Blanches sont des potions conçues pour restaurer le chakra de manière progressive sur une longue durée. Contrairement aux fioles bleues qui permettent une récupération rapide, celles-ci diffusent leur effet lentement, alimentant le flux de chakra du corps au fil du temps. Elles sont souvent utilisées lors de périodes de repos, de méditation ou pendant des soins prolongés liés à l’épuisement du chakra.*\n\n*La Fiole Blanche se reconnaît à sa couleur blanche laiteuse et à son odeur douce rappelant la pêche mûre. Une fois consommée, elle procure une sensation de calme et de légèreté mentale, tandis que le chakra se régénère progressivement. La version la plus puissante de cette fiole possède toutefois un effet rare : elle peut augmenter de façon permanente la réserve maximale de chakra de celui qui la boit. Cet effet exceptionnel ne se manifeste qu’une seule fois par individu, pour une raison que les alchimistes ne parviennent toujours pas à expliquer.*\n\n| Recette |  |  |  |  |  |\n| :-: | :-: | :-: | :-: | :-: | :-: |\n| Solvant | Essence | Amplificateur | Catalyseur | Stabilisateur | Amplificateur majeur |\n| Fiole | Régénération chakra | Régénération chakra | Régénération chakra | Régénération chakra | Régénération chakra |\n\n| Petite fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 7 Ro | Novice | Régénère 5 chakra chaque tour. Dure 3 tours |\n\n| Fiole blanche moyenne |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 35 Ro | Apprenti | Régénère 10 {{chakra\\|chakra}} chaque tour. Dure 3 tours |\n\n| Super fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 75 Ro | Avancé | Régénère 20 chakra chaque tour. Dure 3 tours |\n\n| Méga fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 170 Ro | Expert | Régénère 40 chakra chaque tour. Dure 3 tours |\n\n| Ultime fiole blanche |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 300 Ro | Maître | Augmente la chakra maximum de 10 (une fois par personnage) |\n"}');
