INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.797Z-000000-82c236a8-4538-4ef6-95e9-7722d68452d5', 30, '2026-10-17T15:38:46Z', 'Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-degoutant"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-etrange"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-amer"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-immonde"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:fiole-blanche-moyenne"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:meg', NULL, 'page', '{"id":"ressources/fiole-jaune"}', 'modifier', '{"corps_md":"*Les Fioles Jaunes sont des potions conçues pour restaurer la Barrière, cette seconde peau magique qui protège le corps des coups les plus dangereux. Très utilisées par les aventuriers, les soldats et les mages de combat, elles permettent de reconstituer rapidement cette protection énergétique après qu’elle a été brisée ou affaiblie. Une Barrière active peut absorber les dégâts avant que la santé n’en pâtisse.*\n\n*La Fiole Jaune se reconnaît facilement à sa teinte jaune lumineuse et à son goût légèrement acide rappelant le citron. Lorsqu’elle est bue, une sensation de picotement parcourt brièvement la peau avant qu’une fine aura protectrice ne se reforme autour du corps du buveur, recréant cette seconde enveloppe magique prête à encaisser les prochains chocs.*\n\n| Recette |  |  |  |  |  |\n| :-: | :-: | :-: | :-: | :-: | :-: |\n| Solvant | Essence | Amplificateur | Catalyseur | Stabilisateur | Amplificateur majeur |\n| Fiole | Barrière | Barrière | Barrière | Barrière | Barrière |\n\n| Petite fiole jaune |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 2 Ro | Novice | Récupère 2d8 + 5 barrière |\n\n| Fiole jaune moyenne |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 10 Ro | Apprenti | Récupère 3d8 + 10 barrière |\n\n| Super fiole jaune |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 25 Ro | Avancé | Récupère 4d8 + 20 barrière |\n\n| Méga fiole jaune |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 60 Ro | Expert | Récupère 5d8 + 40 barrière |\n\n| Ultime fiole jaune |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 100 Ro | Maître | Récupère 100% de barrière |\n"}', '{"corps_md":"*Les Fioles Jaunes sont des potions conçues pour restaurer la Barrière, cette seconde peau magique qui protège le corps des coups les plus dangereux. Très utilisées par les aventuriers, les soldats et les mages de combat, elles permettent de reconstituer rapidement cette protection énergétique après qu’elle a été brisée ou affaiblie. Une Barrière active peut absorber les dégâts avant que la santé n’en pâtisse.*\n\n*La Fiole Jaune se reconnaît facilement à sa teinte jaune lumineuse et à son goût légèrement acide rappelant le citron. Lorsqu’elle est bue, une sensation de picotement parcourt brièvement la peau avant qu’une fine aura protectrice ne se reforme autour du corps du buveur, recréant cette seconde enveloppe magique prête à encaisser les prochains chocs.*\n\n| Recette |  |  |  |  |  |\n| :-: | :-: | :-: | :-: | :-: | :-: |\n| Solvant | Essence | Amplificateur | Catalyseur | Stabilisateur | Amplificateur majeur |\n| Fiole | Barrière | Barrière | Barrière | Barrière | Barrière |\n\n| Petite fiole jaune |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 2 Ro | Novice | Récupère 2d8 + 5 barrière |\n\n| Fiole jaune moyenne |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 10 Ro | Apprenti | Récupère 3d8 + 10 {{barriere\\|barrière}} |\n\n| Super fiole jaune |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 25 Ro | Avancé | Récupère 4d8 + 20 barrière |\n\n| Méga fiole jaune |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 60 Ro | Expert | Récupère 5d8 + 40 barrière |\n\n| Ul