INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.797Z-000000-82c236a8-4538-4ef6-95e9-7722d68452d5', 40, '2026-10-17T15:38:46Z', 'Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-degoutant"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-etrange"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-amer"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-immonde"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:fiole-blanche-moyenne"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:meg', NULL, 'page', '{"id":"ressources/fiole-mauve"}', 'modifier', '{"corps_md":"*Les Fioles Mauves sont des potions plus complexes capables de restaurer à la fois la santé physique et le chakra. Leur fabrication demande un savoir-faire bien plus avancé que celui requis pour les fioles classiques. Pour cette raison, elles sont plus rares et possèdent une valeur élevée, particulièrement auprès des aventuriers qui doivent souvent gérer à la fois leurs blessures et l’épuisement de leur chakra.*\n\n*La Fiole Mauve se distingue par sa couleur violet profond et par son odeur sucrée rappelant le raisin mûr. Lorsqu’elle est consommée, une sensation douce et enveloppante traverse le corps : la chaleur de la régénération physique se mêle à une fraîcheur légère qui ravive le flux de chakra.*\n\n| Recette |  |  |  |  |  |\n| :-: | :-: | :-: | :-: | :-: | :-: |\n| Solvant | Essence | Amplificateur | Catalyseur | Stabilisateur | Amplificateur majeur |\n| Fiole | Santé + Chakra | Santé + Chakra | Santé + Chakra | Santé + Chakra | Santé + Chakra |\n\n| Petite fiole mauve |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 5 Ro | Novice | Récupère 2d8 + 5 santé et chakra |\n\n| Fiole mauve moyenne |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 25 Ro | Ap