INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.797Z-000000-82c236a8-4538-4ef6-95e9-7722d68452d5', 59, '2026-10-17T15:38:46Z', 'Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-degoutant"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-etrange"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-amer"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-immonde"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:fiole-blanche-moyenne"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:meg', NULL, 'potion', '{"ressource_id":"ressources/fiole-orange#potion:fiole-orange-moyenne"}', 'modifier', '{"effet":"Récupère 3d8 + 10 santé et barrière"}', '{"effet":"Récupère 3d8 + 10 santé et {{barriere|barrière}}"}');
INSERT INTO historique_modification (lot_id, rang, fait_le, resume, version, table_nom, cle, operation, avant, apres) VALUES ('2026-10-17T15:38:46.797Z-000000-82c236a8-4538-4ef6-95e9-7722d68452d5', 60, '2026-10-17T15:38:46Z', 'Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-degoutant"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:bloc-etrange"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-amer"} : Effet ; Potion {"ressource_id":"ressources/alchimie-primitive#potion:breuvage-immonde"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:fiole-blanche-moyenne"} : Effet ; Potion {"ressource_id":"ressources/fiole-blanche#potion:meg', NULL, 'page', '{"id":"ressources/fiole-orange"}', 'modifier', '{"corps_md":"*Les Fioles Orange sont des potions capables de restaurer à la fois la santé et la barrière magique. Leur création demande un travail délicat et un bon savoir-faire. Pour cette raison, ces fioles sont plus difficiles à produire que les préparations simples et sont particulièrement prisées des guerriers qui souhaitent à la fois refermer leurs blessures et rétablir leur protection magique.*\n\n*La Fiole Orange se reconnaît facilement à sa couleur orange vive et à son odeur fraîche d’orange. Lorsqu’elle est consommée, une chaleur réconfortante traverse le corps tandis qu’une sensation de picotement parcourt la peau. Les blessures commencent alors à se refermer progressivement tandis qu’une fine barrière magique se reforme autour du buveur, lui rendant à la fois sa vitalité et sa protection.*\n\n| Recette |  |  |  |  |  |\n| :-: | :-: | :-: | :-: | :-: | :-: |\n| Solvant | Essence | Amplificateur | Catalyseur | Stabilisateur | Amplificateur majeur |\n| Fiole | Santé + Barrière | Santé + Barrière | Santé + Barrière | Santé + Barrière | Santé + Barrière |\n\n| Petite fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 5 Ro | Novice | Récupère 2d8 + 5 santé et barrière |\n\n| Fiole orange moyenne |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 25 Ro | Apprenti | Récupère 3d8 + 10 santé et barrière |\n\n| Super fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 60 Ro | Avancé | Récupère 4d8 + 20 santé et barrière |\n\n| Méga fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 130 Ro | Expert | Récupère 5d8 + 40 santé et barrière |\n\n| Ultime fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 250 Ro | Maître | Récupère 100% de santé et barrière |\n"}', '{"corps_md":"*Les Fioles Orange sont des potions capables de restaurer à la fois la santé et la barrière magique. Leur création demande un travail délicat et un bon savoir-faire. Pour cette raison, ces fioles sont plus difficiles à produire que les préparations simples et sont particulièrement prisées des guerriers qui souhaitent à la fois refermer leurs blessures et rétablir leur protection magique.*\n\n*La Fiole Orange se reconnaît facilement à sa couleur orange vive et à son odeur fraîche d’orange. Lorsqu’elle est consommée, une chaleur réconfortante traverse le corps tandis qu’une sensation de picotement parcourt la peau. Les blessures commencent alors à se refermer progressivement tandis qu’une fine barrière magique se reforme autour du buveur, lui rendant à la fois sa vitalité et sa protection.*\n\n| Recette |  |  |  |  |  |\n| :-: | :-: | :-: | :-: | :-: | :-: |\n| Solvant | Essence | Amplificateur | Catalyseur | Stabilisateur | Amplificateur majeur |\n| Fiole | Santé + Barrière | Santé + Barrière | Santé + Barrière | Santé + Barrière | Santé + Barrière |\n\n| Petite fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 5 Ro | Novice | Récupère 2d8 + 5 santé et barrière |\n\n| Fiole orange moyenne |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 25 Ro | Apprenti | Récupère 3d8 + 10 santé et {{barriere\\|barrière}} |\n\n| Super fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 60 Ro | Avancé | Récupère 4d8 + 20 santé et barrière |\n\n| Méga fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 130 Ro | Expert | Récupère 5d8 + 40 santé et barrière |\n\n| Ultime fiole orange |  |  |\n| :-: | :-: | :-: |\n| Prix | Niveau | Effet |\n| 250 Ro | Maître | Récupère 100% de santé et barrière |\n"}');
